// Indexed lookup
export const LESSON_INDEX: Record<string, LessonEntry> = Object.fromEntries(
  LESSONS.map((l) => [`${l.chapter}/${l.slug}`, l]),
);

export function getLessonsByChapter(chapter: string): LessonEntry[] {
  return LESSONS.filter((l) => l.chapter === chapter)
    .sort((a, b) => a.frontmatter.order - b.frontmatter.order);
}
